FUNCTIONS=[
dict(id='FR01',name='Chọn và tìm kiếm địa điểm',actor='A01',ui='UI01 và thanh đầu trang',purpose='Xác định địa điểm dùng chung cho chỉ số, bản đồ, cảnh báo, báo cáo và hội thoại.',pre='Danh mục địa điểm đã tải thành công. Ứng dụng không ở trạng thái khóa lựa chọn do đang chat hoặc xử lý báo cáo.',inputs='Người sử dụng chọn MaDiaDiem trong select hoặc nhập từ khóa tối đa 80 ký tự vào ô tìm kiếm. Từ khóa được chuẩn hóa để tìm không dấu; kết quả có thể là địa điểm hoặc mục chức năng.',flow=['Tải GET /api/diadiem và tạo các nhóm lựa chọn từ danh mục.','Lọc gợi ý theo từ khóa; người sử dụng chọn bằng chuột hoặc phím mũi tên và Enter.','Nếu là địa điểm, cập nhật lựa chọn, lưu mã vào localStorage và phát locationchange; nếu là chức năng, điều hướng tới hash tương ứng.','Các thành phần nạp lại dữ liệu theo mã mới; kết quả của yêu cầu cũ được bỏ qua.'],out='Sau thao tác, tên địa điểm và mã dùng trong yêu cầu API thống nhất. Tải lại trang giữ lựa chọn hợp lệ gần nhất. Tìm kiếm không làm thay đổi danh mục gốc.',errors='Không có kết quả thì hiển thị trạng thái tương ứng. Danh mục lỗi có nút thử lại. Mã gửi trực tiếp không thuộc danh mục bị API từ chối với HTTP 400; mã không được tự đổi sang một nơi khác.',tech='static/locations.js, dashboard.js và location_catalog.get_location. GET /api/diadiem đồng bộ metadata qua LocationStore. Kho liên quan: DiaDiem và locations.json.',rules='BR01, BR14',test='TC01, TC02'),
dict(id='FR02',name='Lấy địa điểm gần nhất từ vị trí hiện tại',actor='A01',ui='UI01',purpose='Rút ngắn việc chọn địa điểm bằng cách đối chiếu vị trí thiết bị với các tọa độ sẵn có.',pre='Danh mục đã sẵn sàng, trình duyệt hỗ trợ Geolocation và trang được mở trong ngữ cảnh an toàn như localhost hoặc HTTPS.',inputs='Nút Lấy vị trí hiện tại yêu cầu quyền truy cập vị trí. Tọa độ latitude và longitude phải là số hữu hạn trong phạm vi địa lý hợp lệ.',flow=['Người sử dụng nhấn nút; giao diện hiển thị trạng thái đang định vị và vô hiệu hóa thao tác trùng.','Trình duyệt xin quyền, lấy tọa độ với timeout 12 giây và không dùng tọa độ cũ.','Tính khoảng cách Haversine từ thiết bị tới từng địa điểm trong danh mục, chọn giá trị nhỏ nhất.','Đặt mã tìm được vào danh sách và gọi lại luồng thay đổi địa điểm; hiển thị tên và khoảng cách ước tính.'],out='Kết quả là một địa điểm đã tồn tại trong danh mục, không tạo địa điểm mới và không xác định trạm đo gần nhất. Tọa độ thiết bị chỉ được xử lý trong trình duyệt.',errors='Từ chối quyền, không xác định được vị trí, quá thời gian hoặc tọa độ không hợp lệ đều có thông báo riêng. Người sử dụng vẫn chọn thủ công. Phản hồi GPS cũ không ghi đè lựa chọn mới.',tech='static/locations.js: locateNearest, distanceKm và selectPlace. Không có API nhận tọa độ GPS của thiết bị; các API tiếp theo chỉ nhận MaDiaDiem.',rules='BR01, BR14',test='TC03'),
dict(id='FR03',name='Cập nhật và lưu dữ liệu môi trường',actor='A01, E01, E02',ui='UI01',purpose='Tạo snapshot thống nhất của dữ liệu nguồn, kết quả đánh giá và cảnh báo tại một địa điểm.',pre='Mã địa điểm hợp lệ; SQL Server truy cập được. Nguồn bên ngoài chỉ được gọi khi không có snapshot còn hạn.',inputs='Nút Cập nhật dữ liệu hoặc chu kỳ tải tự động gửi location dạng chuỗi. GET và POST /api/capnhat đều được khai báo; giao diện hiện dùng GET.',flow=['Lấy khóa riêng cho địa điểm và kiểm tra cache 600 giây; nếu cần, đọc snapshot đã lưu còn hạn trong SQL.','Khi cache hết hạn, lấy nhiệt độ, độ ẩm, dữ liệu không khí và phần tiếng ồn phù hợp.','Tạo cảnh báo theo ngưỡng và phân tích theo AQI; gọi hai bộ phân loại RF khi đủ năm giá trị.','Trong một giao dịch, chèn NguonDL, các CanhBao và PhanTichAI, cập nhật ChiTiet rồi commit; đặt cache và trả JSON.'],out='JSON gồm Manguon, ThoiGian, DiaDiem, DuLieu, DuDoanRF, CanhBao và PhanTich. Snapshot mới có mã nguồn duy nhất; cảnh báo và phân tích cùng tham chiếu mã này.',errors='Nguồn HTTP lỗi trả 502; SQL lỗi trả thông báo chung và 503. RF lỗi hoặc thiếu trường không chặn lưu số liệu. Cập nhật còn trong thời hạn cache trả lại snapshot hiện có, không tạo bản ghi mới.',tech='app.py: capnhat, update_environment, fetch_environment, build_alerts, build_analysis. Kho ghi: NguonDL, CanhBao, PhanTichAI; DiaDiem được chuẩn bị trước.',rules='BR01–BR06',test='TC04, TC05, TC06'),
dict(id='FR04',name='Xem các chỉ số môi trường',actor='A01',ui='UI01 và UI02',purpose='Trình bày kết quả giám sát theo địa điểm bằng chỉ số, đơn vị và trạng thái dễ đối chiếu.',pre='Giao diện đã có snapshot hợp lệ hoặc nhận được trạng thái tải lỗi.',inputs='Dữ liệu JSON từ FR03. Các trường chính là US_AQI, PM25, PM10, NhietDo, DoAm và TiengOn; metadata thời gian nguồn và tiếng ồn đi cùng snapshot.',flow=['Đối chiếu phiên yêu cầu và địa điểm đang chọn trước khi cập nhật DOM.','Điền các giá trị, đơn vị và trạng thái thông số; đặt màu, mức AQI và nội dung phân tích.','Cập nhật thời điểm lấy dữ liệu và ghi chú nguồn tiếng ồn.','Giữ dữ liệu cũ cùng thông báo khi tải mới lỗi tại cùng địa điểm; khi đổi nơi thì xóa số cũ trước khi tải.'],out='Người sử dụng xem được năm chỉ số và US AQI. Thanh tiến trình chỉ phục vụ tỷ lệ hiển thị theo cấu hình, không phải toàn bộ thang chuẩn pháp lý.',errors='Trường thiếu hiển thị dấu gạch hoặc trạng thái chưa có dữ liệu. Lỗi tải không được tạo cảm giác số cũ thuộc địa điểm mới. Mức AQI và kết quả RF được hiển thị tách biệt.',tech='static/script.js: renderCurrent, renderAnalysis, renderPrediction, renderCurrentFailed; static/index.html. GET /api/dulieu/moinhat cung cấp bản ghi gần nhất khi cần đọc lại.',rules='BR03, BR04, BR06, BR14',test='TC02, TC06, TC07'),
dict(id='FR05',name='Tương tác với bản đồ địa điểm',actor='A01, E03',ui='UI03',purpose='Đặt dữ liệu môi trường vào bối cảnh không gian và giúp người sử dụng nhận biết tọa độ tham chiếu.',pre='Leaflet đã nạp; địa điểm hiện tại có tọa độ hợp lệ.',inputs='Các thao tác kéo, phóng to, thu nhỏ, nhấn marker, về địa điểm đã chọn, toàn màn hình và mở bản đồ lớn.',flow=['Khởi tạo nền OpenStreetMap và các điều khiển Leaflet.','Đặt marker thời tiết và không khí theo tọa độ địa điểm; marker tiếng ồn dùng tọa độ tham chiếu riêng khi phù hợp.','Nhấn marker để xem tên, tọa độ và thông tin nguồn.','Khi đổi địa điểm, bỏ marker cũ, tạo marker mới và đưa vùng nhìn về nơi được chọn.'],out='Bản đồ hiển thị đúng địa điểm; liên kết mở bản đồ lớn mang tọa độ tương ứng. Di chuyển vùng nhìn không tự thay danh mục địa điểm.',errors='Nếu nền bản đồ không tải được, phần tham chiếu vị trí vẫn có thể hiển thị và giao diện có thao tác thử lại. Toàn màn hình phụ thuộc khả năng của trình duyệt.',tech='static/map.js và thư viện static/vendor/leaflet. Nền bản đồ được tải trực tiếp trong trình duyệt từ OpenStreetMap; dữ liệu mẫu AQI thuộc FR06.',rules='BR01, BR14',test='TC08'),
dict(id='FR06',name='Hiển thị lớp màu AQI theo vùng',actor='A01, E01',ui='UI03',purpose='Biểu diễn phân bố AQI từ các điểm lưới của mô hình trong vùng đang xem.',pre='Phạm vi bản đồ hợp lệ và giao với vùng phục vụ của API. Có ít nhất một phần mẫu dữ liệu dùng được.',inputs='location và bốn giới hạn south, west, north, east dạng số. Giao diện có công tắc lớp màu và độ đậm 25–85%, mặc định 68%.',flow=['Xác định vùng, tạo lưới lấy mẫu với số điểm không vượt 196.','Đọc mẫu còn hiệu lực trong giờ hiện tại từ bộ nhớ và SQL; gọi Open-Meteo cho những điểm còn thiếu.','Trả ma trận AQI, PM25, các trục tọa độ, thời gian nguồn và metadata độ phân giải.','Trình duyệt nội suy giữa các góc hợp lệ, tô theo sáu mức AQI và đặt độ đậm đã chọn.'],out='Lớp phủ là biểu diễn nội suy từ dữ liệu mô hình CAMS Global. Nhấn bản đồ có thể xem giá trị ước tính tại vị trí đó; đây không phải bản ghi đo mới của một cảm biến.',errors='Phạm vi thiếu hoặc sai trả 400. Nguồn lỗi hoàn toàn trả 502; thiếu một phần trả cảnh báo và để trống phần không đủ dữ liệu. Mẫu không được tự gán 0.',tech='air_quality_map.py: make_grid, AirMapRepository.get_samples và grid; static/air-overlay.js. API GET /api/bando/khongkhi; kho MauBanDoKhongKhi.',rules='BR03, BR13, BR14',test='TC09, TC10'),
dict(id='FR07',name='Theo dõi xu hướng PM2.5',actor='A01',ui='UI04',purpose='Cho phép đối chiếu các snapshot PM2.5 gần đây trong cùng địa điểm.',pre='Lịch sử trả về có thể có dữ liệu, rỗng hoặc một số giá trị thiếu.',inputs='GET /api/dulieu/lichsu với location và limit. Giao diện dùng limit=12; API giới hạn hợp lệ từ 1 đến 500.',flow=['Đọc các bản ghi mới nhất của địa điểm theo thời gian và mã nguồn giảm dần.','Sắp thứ tự trình bày theo thời gian tăng dần và lấy các điểm PM2.5 sử dụng được.','Tính miền giá trị, chọn bước chia trục số phù hợp và dựng đường biểu diễn trên Canvas.','Hiển thị giá trị gần nhất, nhãn xu hướng và các mốc thời gian; vẽ lại khi thay đổi kích thước màn hình.'],out='Đồ thị có trục tung số, đơn vị µg/m³ và các mốc thời gian. Nhận xét tăng giảm dựa trên lịch sử snapshot, không phải dự báo tương lai.',errors='Lịch sử rỗng và tải lỗi có trạng thái riêng. Dữ liệu thiếu tạo khoảng trống thay vì điểm đo bằng 0. Phản hồi của địa điểm cũ bị loại bỏ.',tech='app.dulieu_lichsu; static/script.js: renderTrend, describeTrend, drawTrend. Đọc NguonDL; không tạo bản ghi mới.',rules='BR03, BR14',test='TC11'),
dict(id='FR08',name='Xem lịch sử cảnh báo',actor='A01',ui='UI06 dưới dạng bảng thông báo',purpose='Cho phép tra cứu các cảnh báo môi trường gần nhất của nơi đang giám sát.',pre='Địa điểm đã được xác định; cảnh báo có thể chưa phát sinh.',inputs='Nhấn biểu tượng chuông trên đầu trang. GET /api/canhbao nhận location và limit; giao diện lấy 8, API mặc định 20 và giới hạn tối đa 200.',flow=['Đọc CanhBao liên kết NguonDL theo mã địa điểm.','Hiển thị loại, mức, nội dung và thời gian; cập nhật số cảnh báo đã tải trên chuông.','Người sử dụng mở bảng bằng chuông và đóng bằng X, Esc hoặc chuyển ngữ cảnh thích hợp.','Khi đổi địa điểm, tải lại cảnh báo và xóa trạng thái của nơi cũ.'],out='Lịch sử chỉ chứa cảnh báo của địa điểm hiện tại. Con số trên chuông là số mục gần nhất đang tải, không phải số cảnh báo chưa đọc có lưu bền.',errors='Chưa có cảnh báo hiển thị trạng thái rỗng; lỗi tải hiển thị thông báo và khả năng thử lại. Cảnh báo không có vòng đời xác nhận, phân công hoặc đóng trong phiên bản hiện tại.',tech='app.canhbao; static/script.js: renderAlerts; static/dashboard.js: setNotifications và syncAlerts. Đọc CanhBao qua NguonDL.',rules='BR01, BR05, BR14',test='TC12'),
dict(id='FR09',name='Xem phân tích và phân loại Random Forest',actor='A01',ui='UI05',purpose='Tách phần diễn giải AQI theo quy tắc khỏi nhãn dự đoán của mô hình minh họa.',pre='Có snapshot và trạng thái DuDoanRF. Đủ năm đặc trưng mới chạy được mô hình.',inputs='Năm giá trị PM25, PM10, NhietDo, DoAm, TiengOn. Giá trị phải chuyển được thành số hữu hạn; thứ tự đặc trưng phải khớp model bundle.',flow=['Kiểm tra đầy đủ giá trị và danh sách đặc trưng.','Nạp bundle joblib cục bộ một lần và tạo DataFrame đúng thứ tự.','Chạy hai classifier cho chất lượng không khí và mức tiếng ồn.','Trả nhãn tiếng Việt và TrangThai; giao diện hiển thị cùng phần phân tích AQI nhưng thành khối riêng.'],out='TrangThai là ok, thieu_du_lieu hoặc loi_mo_hinh. Nhãn RF thể hiện kết quả mô hình được huấn luyện theo nhãn của dự án; phân tích AQI được lưu trong PhanTichAI do build_analysis tạo.',errors='Thiếu một trường trả danh sách Thieu. Lỗi nạp hoặc suy luận không làm mất dữ liệu nguồn. Tên PhanTichAI không có nghĩa là mọi nội dung trong bảng do mô hình ngôn ngữ sinh ra.',tech='environment_predictor.py: FEATURE_FIELDS, load_model, predict_environment; app.build_analysis; static/script.js: renderPrediction. Bundle environment_rf.joblib; snapshot lưu kết quả trong ChiTiet.',rules='BR03, BR06',test='TC06, TC13'),
dict(id='FR10',name='Tạo và lưu báo cáo môi trường',actor='A01',ui='UI07',purpose='Tổng hợp dữ liệu đã ghi nhận trong một kỳ thành báo cáo có thể mở lại.',pre='Địa điểm hợp lệ và SQL Server sẵn sàng. Kỳ không có bản ghi vẫn có thể tạo báo cáo rỗng.',inputs='POST /api/baocao nhận JSON days là số nguyên 1, 7 hoặc 30 và location là mã danh mục. Nút Tạo và lưu báo cáo bị khóa trong lúc xử lý.',flow=['Kiểm tra kiểu và giá trị kỳ báo cáo; lấy thời gian tạo và mốc đầu kỳ.','Đọc NguonDL cùng các CanhBao đúng mã địa điểm, trong khoảng đầu và cuối kỳ.','Chuẩn hóa giá trị, tính số bản ghi, min, max, trung bình phù hợp, số thiếu, số lần vượt ngưỡng và nhóm thời gian.','Lưu toàn bộ nội dung JSON trong BaoCaoMT rồi trả HTTP 201 kèm MaBaoCao; cập nhật màn hình và lịch sử.'],out='Báo cáo có địa điểm, kỳ, thời gian tạo, thống kê, dữ liệu nguồn và cảnh báo. Nội dung đã lưu giữ nguyên khi người sử dụng mở lại sau đó.',errors='Kỳ sai, số thực hoặc boolean trả 400. SQL lỗi trả 503. Nếu trình duyệt hết thời gian chờ, trạng thái chưa xác định việc lưu được xử lý bằng tải lại lịch sử; không coi timeout là chắc chắn chưa lưu.',tech='environment_reports.py: build_report, ReportRepository.create, create_report_blueprint; static/reports.js. Đọc NguonDL và CanhBao; ghi BaoCaoMT.',rules='BR07, BR08, BR14',test='TC14, TC15'),
dict(id='FR11',name='Tra cứu và mở báo cáo đã lưu',actor='A01',ui='UI07',purpose='Sử dụng lại đúng nội dung báo cáo đã tạo thay vì tính lại theo dữ liệu hiện tại.',pre='Người sử dụng đang ở màn hình báo cáo và địa điểm hợp lệ.',inputs='GET /api/baocao nhận location, limit và offset; mặc định limit=10, tối đa 50. Chọn Mở báo cáo gửi MaBaoCao trên đường dẫn và mã địa điểm trong query.',flow=['Tải các báo cáo theo địa điểm, sắp mới nhất trước.','Nhấn Xem thêm để tăng offset và ghép các mục tiếp theo.','Khi mở một mã, repository tìm đồng thời theo MaBaoCao và MaDiaDiem.','Đọc NoiDung JSON đã lưu, kiểm tra mã địa điểm và dựng lại phần thống kê, biểu đồ cùng bảng dữ liệu.'],out='Nội dung hiển thị khớp snapshot báo cáo đã lưu. Mở lại không tạo báo cáo mới.',errors='Mã không tồn tại hoặc không thuộc địa điểm được yêu cầu trả 404. Lỗi mạng và lỗi SQL có thông báo riêng. Đổi nơi xóa báo cáo đang xem của nơi cũ.',tech='ReportRepository.list và get; static/reports.js: openReport và phần lịch sử. Đọc BaoCaoMT; không ghi dữ liệu khi mở.',rules='BR01, BR07, BR14',test='TC15, TC16'),
dict(id='FR12',name='Xuất CSV và in báo cáo',actor='A01',ui='UI07',purpose='Đưa nội dung báo cáo đang mở ra tệp dữ liệu hoặc bản in.',pre='Đã mở báo cáo hợp lệ. CSV yêu cầu báo cáo có bản ghi; in yêu cầu có báo cáo hiện tại.',inputs='Nút Tải CSV và In báo cáo. Dữ liệu đầu vào lấy từ báo cáo hiện tại trên trình duyệt, không đọc một kỳ khác từ API.',flow=['Kiểm tra trạng thái báo cáo và địa điểm hiện tại.','Với CSV, tạo các cột dữ liệu và số cảnh báo tương ứng từng bản ghi; mã hóa UTF-8 có BOM, xử lý dấu phân cách và nội dung có thể bị hiểu là công thức.','Tạo Blob và tải tệp có tên chứa mã địa điểm cùng mã báo cáo.','Với in, gọi window.print; CSS in ẩn menu và chatbot. Người sử dụng có thể chọn máy in hoặc lưu PDF trong hộp thoại trình duyệt.'],out='CSV có 17 cột và nhận diện đúng báo cáo. Bản in sử dụng nội dung đang xem; máy chủ không cung cấp endpoint xuất PDF trong phiên bản này.',errors='Khi chưa có báo cáo hoặc đang bận, nút bị vô hiệu hóa. Báo cáo rỗng không xuất CSV. Hủy hộp thoại in không thay đổi báo cáo đã lưu.',tech='static/reports.js: csvCell, trình xử lý reportCsv và reportPrint; quy tắc @media print trong CSS. Không ghi thêm vào cơ sở dữ liệu.',rules='BR07, BR08',test='TC17'),
dict(id='FR13',name='Gửi và điều khiển hội thoại',actor='A01',ui='UI08',purpose='Cho phép trao đổi với Xanh Non trong cửa sổ chat nổi mà không rời chức năng đang xem.',pre='Widget đã sẵn sàng. Câu hỏi không rỗng và lịch sử đúng cấu trúc.',inputs='message tối đa 8.000 ký tự; history tối đa tám cặp user–assistant; location; stream; cờ learn_from_chat. Giao diện có mở, đóng, gửi, dừng, bắt đầu lại và tiếp tục khi câu trả lời bị cắt.',flow=['Người sử dụng mở bong bóng, nhập câu hỏi và gửi; giao diện khóa lựa chọn địa điểm trong lúc tạo câu trả lời.','API kiểm tra dữ liệu, chuẩn bị snapshot và điều phối các nhánh trả lời.','Với stream, máy chủ phát status, delta và done hoặc error; widget ghép nội dung theo sự kiện.','Khi hoàn tất, lưu cặp hỏi đáp trong bộ nhớ của địa điểm, mở khóa thao tác và đánh dấu phản hồi mới nếu widget đang thu gọn.'],out='Câu trả lời hiển thị dạng văn bản an toàn. Thu gọn không xóa hội thoại; bắt đầu lại xóa ngữ cảnh tại giao diện. Không có hồ sơ hội thoại gắn tài khoản đăng nhập.',errors='HTTP 400 cho dữ liệu sai; 413 cho body quá lớn; 429 khi khóa sinh đang bận; 503 khi thiếu mô hình. Ngắt kết nối được truyền tới xử lý hủy, không biến câu dở thành một cặp lịch sử hoàn chỉnh.',tech='static/chat.js; app.chat; chatbot.validate_chat, generate_reply và stream_reply; NativeChatbot.generate. Lịch sử thông thường nằm trong bộ nhớ trình duyệt; không có bảng ChatSession.',rules='BR09, BR11, BR14',test='TC18, TC19'),
dict(id='FR14',name='Giữ ngữ cảnh và đọc dữ liệu theo thời gian',actor='A01, E01',ui='UI08',purpose='Hiểu các câu nối tiếp ngắn và lấy đúng dữ liệu hiện tại hoặc dự báo cho nội dung đang trao đổi.',pre='Có câu hỏi và lịch sử user–assistant hợp lệ. Thời gian xử lý dựa trên UTC+7.',inputs='Các cách nói như mai, ngày kia, tối, 18 giờ 30; câu nối tiếp như độ ẩm thì sao hoặc không khí nữa. Địa điểm có thể ở danh mục đang chọn hoặc được nêu trong câu hỏi.',flow=['Xác định chủ đề và lấy các chi tiết ngữ cảnh từ lượt người sử dụng gần nhất còn liên quan.','Giữ hoặc thay địa điểm, ngày và giờ theo thông tin mới; câu hiện tại không tiếp tục dùng mốc dự báo cũ.','Nếu chưa rõ chủ đề hoặc thiếu ngày cho một giờ cụ thể, hỏi lại; nếu đủ, đọc nguồn thời tiết hoặc không khí phù hợp.','Tổng hợp các mẫu giờ có trong cửa sổ yêu cầu và trả đúng trường được hỏi, kèm tên nơi và mốc thời gian.'],out='Câu hỏi nối tiếp dùng cùng chủ đề khi có căn cứ. Dự báo thời tiết hiện có nhiệt độ và độ ẩm; dự báo không khí dùng dữ liệu Open-Meteo/CAMS. Yêu cầu 18:30 được gắn với khoảng dữ liệu giờ tương ứng.',errors='Nguồn thiếu hoặc chuỗi giờ không đủ thì không điền giá trị giả. Đổi sang chủ đề ngoài môi trường dừng kế thừa ngữ cảnh. Số trong câu trả lời cũ không được dùng làm phép đo mới.',tech='chatbot.py: _dialogue_question, _consultation_reply, các nhánh weather/air; chat_time_context.py; chat_clarification.py; chat_weather_data.py; chat_air_data.py. Cache dự báo 600 giây theo nơi, tọa độ và ngày.',rules='BR03, BR09–BR11',test='TC20, TC21'),
dict(id='FR15',name='Giải thích và tư vấn từ tri thức có nguồn',actor='A01',ui='UI08',purpose='Trả lời câu hỏi kiến thức, cách giảm tiếp xúc với bụi và các tình huống môi trường bằng nội dung có nguồn.',pre='Câu hỏi thuộc phạm vi hoặc là giao tiếp cơ bản và giới thiệu chức năng được hệ thống nhận biết.',inputs='Câu hỏi tự nhiên tiếng Việt, gồm các biến thể không dấu và câu ngắn. Người sử dụng có thể yêu cầu ngắn gọn, chi tiết hoặc nêu một hạn chế cụ thể như chưa có máy lọc.',flow=['Chuẩn hóa tiếng Việt, nhận ý định và ưu tiên câu trả lời chuyên biệt đã kiểm tra.','Tìm nội dung phù hợp trong knowledge.json theo câu mẫu, chủ đề hoặc chỉ mục TF-IDF ký tự.','Nếu đã có đáp án chắc chắn, trả trực tiếp; nếu cần mô hình sinh, đưa tri thức và dữ liệu liên quan vào ngữ cảnh.','Làm sạch nội dung trước khi hiển thị, hạn chế lặp số liệu không liên quan và phần hướng dẫn nội bộ.'],out='Trợ lý giải thích khái niệm, đưa cách thực hiện và lý do trong phạm vi nguồn có sẵn. Kho khảo sát có 26 tài liệu; các bộ chat tổng quát không được dùng như nguồn xác nhận kiến thức AQI.',errors='Ngoài phạm vi trả câu giới thiệu cố định. Nội dung chưa đủ căn cứ có thể được hỏi lại hoặc thông báo chưa có dữ liệu cần thiết. Không có chứng nhận độ chính xác chuyên môn chung từ các bài thử hiện có.',tech='chat_scope.py; chat_knowledge.py: practical_answer, concept_answer, retrieve; chat_output.py; chatbot._generate_raw. Kho data/xanhnon/knowledge.json; không có cơ sở dữ liệu vector riêng.',rules='BR10–BR12',test='TC22, TC23'),
dict(id='FR16',name='Tiếp nhận góp ý và câu hỏi mới',actor='A01; A02 duyệt bằng công cụ',ui='UI08',purpose='Ghi nhận phản hồi hữu ích và biến thể câu hỏi phù hợp để sử dụng trong quy trình cải thiện có kiểm tra.',pre='Hội thoại có ngữ cảnh cần thiết. Nguồn gửi đáp ứng kiểm tra Origin đối với thao tác ghi; tự học được bật cho các yêu cầu phù hợp.',inputs='Tin nhắn xác nhận hữu ích đi qua /api/chat; câu hỏi mới được quan sát khi learn_from_chat=true. API POST /api/chat/feedback tồn tại cho payload góp ý nhưng giao diện không có bộ nút đánh giá riêng.',flow=['Nhận biết lời xác nhận hữu ích và lưu payload có fingerprint để tránh ghi trùng.','Với câu hỏi mới, loại dữ liệu nhạy cảm, nội dung ngoài phạm vi và câu thuộc tập kiểm tra; tạo khóa từ câu hỏi cùng ngữ cảnh người dùng.','Chỉ gắn learned nếu đáp án khớp tài liệu ổn định có nguồn chính thức, đúng phiên bản tri thức và chính sách.','Các câu cần số liệu hoặc nguồn được lưu ở trạng thái chờ phù hợp; góp ý chỉ được xuất thành dữ liệu học sau kiểm tra nội dung và riêng tư.'],out='feedback.sqlite3 lưu góp ý và trạng thái duyệt; questions.sqlite3 lưu câu hỏi, số lần gặp và liên kết tài liệu. Trọng số mô hình không thay đổi sau mỗi tin nhắn.',errors='Không đọc được kho học không làm dừng hội thoại chính. Nguồn gửi không hợp lệ trả 403; payload góp ý sai trả 400; lỗi lưu góp ý trả 503. Không tái sử dụng một đáp án learned khi hash tri thức hoặc chính sách đã đổi.',tech='chat_feedback.FeedbackStore; record_helpful_message; chat_learning.ConversationLearner.observe; feedback_training_data.py. Hai cơ sở dữ liệu SQLite độc lập với SQL Server.',rules='BR09, BR12',test='TC24, TC25'),
dict(id='FR17',name='Theo dõi trạng thái mô hình',actor='A02; giao diện đọc khi cần',ui='API và công cụ vận hành',purpose='Phân biệt chatbot chưa nạp, đang nạp, sẵn sàng, gặp lỗi hoặc đang bị khóa bởi huấn luyện.',pre='Flask đang chạy. Kiểm tra trạng thái không yêu cầu sinh một câu trả lời.',inputs='GET /api/chat/status không có payload. Trạng thái phụ thuộc runtime và khóa huấn luyện.',flow=['Đọc trạng thái runtime đang giữ trong tiến trình.','Kiểm tra huấn luyện đang hoạt động và cấu hình cho phép sử dụng đồng thời.','Trả state và, nếu phù hợp, background_training.','Người vận hành đối chiếu thông tin với log native, khóa huấn luyện và manifest bản phát hành.'],out='JSON có các trạng thái cold, loading, ready, training hoặc error. ready chỉ xác nhận runtime đã nạp, không đánh giá chất lượng câu trả lời hoặc độ mới dữ liệu.',errors='Máy chủ không chạy thì không nhận được phản hồi HTTP. Runtime nạp lỗi có log và trạng thái error; các nhánh trả lời bằng quy tắc hoặc tri thức có thể hoạt động độc lập với phần sinh mô hình.',tech='app.chat_status; chatbot.runtime_status, _load_runtime, warm_up_chatbot; native_chatbot.py; models/xanhnon-active.json.',rules='BR09, BR12',test='TC26'),
dict(id='FR18',name='Chuẩn bị dữ liệu và huấn luyện cục bộ',actor='A02',ui='Công cụ dòng lệnh và lịch chạy Windows',purpose='Tạo bộ dữ liệu đã lọc và mô hình ứng viên, tách khỏi bản đang phục vụ hội thoại.',pre='Có bộ dữ liệu hợp lệ, mô hình nền hoặc checkpoint có thể sử dụng, đủ RAM và ổ đĩa; không trùng phiên huấn luyện.',inputs='JSONL hội thoại, manifest nguồn, dữ liệu cảm biến đã chuyển thành tình huống và góp ý đã duyệt. Tham số học được truyền cho các script; không có màn hình quản trị huấn luyện trên web.',flow=['Kiểm tra nguồn, hash, trùng câu và giao nhau giữa các tập; chuẩn bị train và validation.','Token hóa toàn bộ mẫu và chỉ tính loss trên token phía assistant.','Kiểm tra RAM, ổ đĩa và khóa chạy; huấn luyện LoRA khi đáp ứng điều kiện.','Lưu checkpoint, đánh giá ứng viên và xuất GGUF riêng. Bản dùng trong ứng dụng được xác định bởi manifest phát hành, không tự coi mọi ứng viên là bản đã áp dụng.'],out='Các sản phẩm gồm JSONL đã lọc, báo cáo tiền kiểm tra, checkpoint hoặc adapter, kết quả đánh giá và bản xuất. Hồ sơ ngày 27/10 ghi nhận 452 mẫu train, 124 validation đã tiền kiểm tra; lịch tự động thực tế đang chờ bộ nhớ.',errors='Thiếu RAM chuyển waiting_for_memory. Dữ liệu không hợp lệ, nguồn trùng hoặc mất trạng thái tối ưu không được coi là một lần tiếp tục học thành công. Khôi phục checkpoint gộp chỉ hỗ trợ đợt LoRA mới, không phục dựng optimizer cũ.',tech='daily_train_xanhnon.py; train_xanhnon.py; training_state.py; training_resume.py; export_xanhnon.py; model_release.py. Lịch XanhNon-Train-Reviewed-Data và các manifest cục bộ.',rules='BR12',test='TC27, TC28')
]

def render_functions(api):
    p,h,label,steps=api
    for i,f in enumerate(FUNCTIONS,1):
        h(f'5.{i+1} {f["id"]} {f["name"]}')
        label('Mục đích và tác nhân.',f['purpose']+' Tác nhân: '+f['actor']+'. Ca sử dụng tương ứng: UC'+f['id'][2:]+'.')
        label('Điều kiện trước.',f['pre'])
        label('Đầu vào và giao diện.',f['inputs']+' Vị trí thao tác: '+f['ui']+'.')
        label('Luồng chính.','')
        steps(f['flow'])
        label('Điều kiện sau và đầu ra.',f['out'])
        label('Luồng thay thế và ngoại lệ.',f['errors'])
        label('Thiết kế và bằng chứng.',f['tech'])
        label('Quy tắc và nghiệm thu.',f['rules']+'. Kiểm thử: '+f['test']+'.')
